import sys

class DivideByZeroException(Exception):
    pass

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a = int(data[0])
    b = int(data[1])
    try:
        if b == 0:
            raise DivideByZeroException
        result = a // b
        print(f"Result: {result}")
    except DivideByZeroException:
        print("Cannot divide by zero")

if __name__ == "__main__":
    main()
